import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

const API = 'http://localhost:8000';

function App() {
  const [file, setFile] = useState(null);
  const [selfie, setSelfie] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState('overview');
  const [history, setHistory] = useState([]);

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    try {
      const res = await axios.get(`${API}/history`);
      setHistory(res.data.history || []);
    } catch (e) { /* ignore */ }
  };

  const handleScan = async () => {
    if (!file) {
      setError('Please select a document to scan.');
      return;
    }
    setLoading(true);
    setError('');
    setResult(null);
    setActiveTab('overview');

    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await axios.post(`${API}/upload`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      if (response.data.error) {
        setError(response.data.error);
      } else {
        setResult(response.data);
        fetchHistory();
      }
    } catch (err) {
      setError('Server not responding. Make sure the backend is running on port 8000.');
    } finally {
      setLoading(false);
    }
  };

  const handleFaceVerify = async () => {
    if (!file || !selfie) {
      setError('Please select both a document and a selfie for face verification.');
      return;
    }
    setLoading(true);
    setError('');

    const formData = new FormData();
    formData.append('document', file);
    formData.append('selfie', selfie);

    try {
      const response = await axios.post(`${API}/verify-face`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      if (response.data.error) {
        setError(response.data.error);
      } else {
        setResult(prev => prev ? { ...prev, face: response.data } : response.data);
        setActiveTab('face');
      }
    } catch (err) {
      setError('Face verification failed.');
    } finally {
      setLoading(false);
    }
  };

  const getVerdictClass = (verdict) => {
    if (!verdict) return '';
    const v = verdict.toLowerCase();
    if (v.includes('genuine')) return 'genuine';
    if (v.includes('fake')) return 'fake';
    if (v.includes('suspicious')) return 'suspicious';
    if (v.includes('review')) return 'review';
    return '';
  };

  const getRiskClass = (level) => {
    if (!level) return '';
    return level.toLowerCase();
  };

  return (
    <>
      <div className="header">
        <div>
          <h1>🛡️ AI-Based Fake Identity & Document Screening System</h1>
          <p>Powered by OCR, Computer Vision & Machine Learning — Border Checkpoint Security</p>
        </div>
      </div>

      <div className="container">
        {/* Upload Section */}
        <div className="upload-section">
          <h2>📄 Upload Document for Screening</h2>
          <p className="upload-desc">
            Supports <strong>Passport, Visa, Aadhaar, PAN, Voter ID, and Driving Licence</strong> documents.
          </p>

          <div className="file-inputs">
            <div className="file-input-group">
              <label>Document Image *</label>
              <input
                type="file"
                accept=".jpg,.jpeg,.png,.pdf"
                onChange={(e) => { setFile(e.target.files[0]); setResult(null); setError(''); }}
              />
            </div>
            <div className="file-input-group">
              <label>Selfie for Face Match (Optional)</label>
              <input
                type="file"
                accept=".jpg,.jpeg,.png"
                onChange={(e) => setSelfie(e.target.files[0])}
              />
            </div>
          </div>

          <div className="btn-row">
            <button className="scan-btn" onClick={handleScan} disabled={loading || !file}>
              {loading ? '⏳ Analyzing...' : '🔍 Start AI Screening'}
            </button>
            {selfie && (
              <button className="scan-btn secondary" onClick={handleFaceVerify} disabled={loading || !file || !selfie}>
                👤 Verify Face Match
              </button>
            )}
          </div>
        </div>

        {/* Loading */}
        {loading && (
          <div className="loading">
            <span className="spinner"></span>
            <div className="loading-steps">
              <div className="loading-step active">🔍 Running OCR text extraction...</div>
              <div className="loading-step">✅ Validating document fields...</div>
              <div className="loading-step">🔬 Performing tampering analysis...</div>
              <div className="loading-step">👤 Detecting face & checking quality...</div>
              <div className="loading-step">🤖 ML classification & risk scoring...</div>
            </div>
          </div>
        )}

        {error && <div className="error-message">❌ {error}</div>}

        {/* Results */}
        {result && (
          <div className="results">
            {/* Overview Card */}
            <div className="overview-card">
              <div className="overview-left">
                <div className={`verdict ${getVerdictClass(result.verdict)}`}>
                  {result.verdict}
                </div>
                <span className={`risk-level ${getRiskClass(result.risk_level)}`}>
                  {result.risk_level} RISK
                </span>
                <div className="doc-type-badge">{result.doc_type}</div>
              </div>
              <div className="overview-right">
                <div className="risk-gauge">
                  <svg viewBox="0 0 120 120" className="gauge-svg">
                    <circle cx="60" cy="60" r="50" fill="none" stroke="#e5e7eb" strokeWidth="10" />
                    <circle
                      cx="60" cy="60" r="50" fill="none"
                      stroke={result.risk_score >= 70 ? '#ef4444' : result.risk_score >= 50 ? '#f97316' : result.risk_score >= 30 ? '#f59e0b' : '#10b981'}
                      strokeWidth="10"
                      strokeDasharray={`${(result.risk_score / 100) * 314} 314`}
                      strokeLinecap="round"
                      transform="rotate(-90 60 60)"
                    />
                  </svg>
                  <div className="gauge-text">
                    <span className="gauge-value">{result.risk_score}</span>
                    <span className="gauge-label">Risk Score</span>
                  </div>
                </div>
                <div className="confidence-text">
                  AI Confidence: <strong>{result.confidence}%</strong>
                </div>
              </div>
            </div>

            {/* Module Scores */}
            {result.module_scores && (
              <div className="module-scores">
                {Object.entries(result.module_scores).map(([key, mod]) => (
                  <div className="module-score-card" key={key}>
                    <div className="module-label">{mod.label}</div>
                    <div className="module-value">{mod.score.toFixed(1)}</div>
                    <div className="score-bar">
                      <div
                        className={`score-bar-fill ${mod.status.toLowerCase()}`}
                        style={{ width: `${Math.min(mod.score, 100)}%` }}
                      ></div>
                    </div>
                    <span className={`risk-level small ${mod.status.toLowerCase()}`}>{mod.status}</span>
                  </div>
                ))}
              </div>
            )}

            {/* Flags */}
            {result.flags && result.flags.length > 0 && (
              <div className="flags-section">
                <h3>🚩 Raised Flags</h3>
                <div className="flags-list">
                  {result.flags.map((flag, i) => (
                    <span key={i} className={`flag-item ${flag.includes('CRITICAL') || flag.includes('BLACKLIST') ? 'critical' : 'warning'}`}>
                      {flag.replace(/_/g, ' ')}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {/* Tabs */}
            <div className="tabs">
              {['overview', 'ocr', 'validation', 'tampering', 'face'].map(tab => (
                <button
                  key={tab}
                  className={`tab ${activeTab === tab ? 'active' : ''}`}
                  onClick={() => setActiveTab(tab)}
                >
                  {tab === 'overview' && '📊 Overview'}
                  {tab === 'ocr' && '📝 OCR'}
                  {tab === 'validation' && '✅ Validation'}
                  {tab === 'tampering' && '🔬 Tampering'}
                  {tab === 'face' && '👤 Face'}
                </button>
              ))}
            </div>

            <div className="tab-content">
              {/* Overview Tab */}
              {activeTab === 'overview' && (
                <div>
                  {/* AI Intelligence Brief */}
                  {result.ai_brief && (
                    <div className="section-box ai-brief-box" style={{ background: '#f8fafc', borderLeft: '4px solid #004aad', padding: '16px', marginBottom: '16px', borderRadius: '8px' }}>
                      <h3 style={{ margin: '0 0 8px 0', display: 'flex', alignItems: 'center', gap: '8px', color: '#004aad', fontSize: '15px' }}>
                        <span>🤖</span> AI Intelligence Assessment (OpenRouter)
                      </h3>
                      <p style={{ margin: 0, fontSize: '14px', lineHeight: '1.6', color: '#334155', whiteSpace: 'pre-line' }}>
                        {result.ai_brief}
                      </p>
                    </div>
                  )}

                  {/* AI Smart Validation Findings */}
                  {result.ai_validation && (
                    <div className="section-box" style={{ background: '#f8fafc', borderLeft: '4px solid #10b981', padding: '16px', marginBottom: '16px', borderRadius: '8px' }}>
                      <h4 style={{ margin: '0 0 8px 0', color: '#0f766e', fontSize: '14px' }}>
                        🧠 AI Semantic Reasoning: {result.ai_validation.ai_assessment} ({((result.ai_validation.confidence || 0) * 100).toFixed(0)}% confidence)
                      </h4>
                      {result.ai_validation.reasoning && (
                        <p style={{ fontSize: '13px', margin: '0 0 8px 0', color: '#475569' }}>
                          {result.ai_validation.reasoning}
                        </p>
                      )}
                      {result.ai_validation.findings && result.ai_validation.findings.length > 0 && (
                        <ul style={{ margin: 0, paddingLeft: '20px', fontSize: '13px', color: '#334155' }}>
                          {result.ai_validation.findings.map((f, idx) => (
                            <li key={idx}>{f}</li>
                          ))}
                        </ul>
                      )}
                    </div>
                  )}

                  {/* Recommendations */}
                  {result.recommendations && result.recommendations.length > 0 && (
                    <div className="recommendations">
                      <h3>📋 Recommendations for Personnel</h3>
                      {result.recommendations.map((rec, i) => (
                        <div key={i} className="recommendation-item">{rec}</div>
                      ))}
                    </div>
                  )}

                  <div className="disclaimer">
                    ⚠️ <strong>Note:</strong> This system strictly checks document authenticity (tampering/editing)
                    and identity-field consistency. It does NOT determine citizenship or legal status.
                  </div>
                </div>
              )}

              {/* OCR Tab */}
              {activeTab === 'ocr' && (
                <div>
                  <h3>📝 Extracted Fields — {result.doc_type}</h3>
                  {result.extracted_fields && Object.keys(result.extracted_fields).length > 0 ? (
                    <div className="fields-table">
                      {Object.entries(result.extracted_fields).map(([key, val]) => {
                        if (key === 'mrz') return null;
                        return (
                          <div className="field-row" key={key}>
                            <span className="field-label">{key.replace(/_/g, ' ').toUpperCase()}</span>
                            <span className={`field-value ${!val ? 'missing' : ''}`}>
                              {val || 'Not detected'}
                            </span>
                          </div>
                        );
                      })}
                    </div>
                  ) : (
                    <p>No structured fields extracted.</p>
                  )}

                  {result.extracted_fields?.mrz && (
                    <div className="section-box">
                      <h4>🔖 MRZ (Machine Readable Zone)</h4>
                      <div className="fields-table">
                        {Object.entries(result.extracted_fields.mrz).map(([key, val]) => (
                          <div className="field-row" key={key}>
                            <span className="field-label">{key.replace(/_/g, ' ').toUpperCase()}</span>
                            <span className="field-value">{val || '—'}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  <div className="section-box">
                    <h4>📄 Raw OCR Text</h4>
                    <div className="extracted-text">{result.extracted_text || 'No text detected.'}</div>
                  </div>
                </div>
              )}

              {/* Validation Tab */}
              {activeTab === 'validation' && (
                <div>
                  <h3>✅ Document Validation Results</h3>
                  {result.validation?.score !== undefined && (
                    <div className="validation-score">
                      Validation Score: <strong>{(result.validation.score * 100).toFixed(1)}%</strong>
                      {' '} — {result.validation.is_valid ? '✅ All critical checks passed' : '❌ Validation issues found'}
                    </div>
                  )}

                  {result.validation?.checks && result.validation.checks.length > 0 ? (
                    <div className="validation-checks">
                      {result.validation.checks.map((check, i) => (
                        <div className="check-item" key={i}>
                          <span className={`check-icon ${check.passed ? 'pass' : 'fail'}`}>
                            {check.passed ? '✅' : '❌'}
                          </span>
                          <span className="check-field">{(check.field || '').replace(/_/g, ' ')}</span>
                          <span className="check-type">{(check.check || '').replace(/_/g, ' ')}</span>
                          <span className="check-detail">{check.detail}</span>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p>No validation checks performed.</p>
                  )}
                </div>
              )}

              {/* Tampering Tab */}
              {activeTab === 'tampering' && (
                <div>
                  <h3>🔬 Tampering Detection Analysis</h3>
                  <div className="tampering-grid">
                    {/* ELA */}
                    <div className="tampering-card">
                      <h4>Error Level Analysis (ELA)</h4>
                      <p className="tamper-score">Score: <strong>{(result.tampering?.ela?.score || 0).toFixed(3)}</strong></p>
                      {result.heatmap_url && (
                        <div className="heatmap">
                          <img src={`${API}${result.heatmap_url}`} alt="ELA Heatmap" />
                          <p className="heatmap-caption">Bright areas indicate potential digital manipulation.</p>
                        </div>
                      )}
                    </div>

                    {/* Metadata */}
                    <div className="tampering-card">
                      <h4>EXIF Metadata Analysis</h4>
                      <p className="tamper-score">Score: <strong>{(result.tampering?.metadata?.score || 0).toFixed(3)}</strong></p>
                      <p>EXIF Present: {result.tampering?.metadata?.has_exif ? '✅ Yes' : '❌ No'}</p>
                      {result.tampering?.metadata?.software_detected && (
                        <p className="flag-item warning">⚠️ Editing Software: {result.tampering.metadata.software_detected}</p>
                      )}
                      {result.tampering?.metadata?.flags?.map((f, i) => (
                        <p key={i} className="flag-item warning">🚩 {f.replace(/_/g, ' ')}</p>
                      ))}
                    </div>

                    {/* Copy-Move */}
                    <div className="tampering-card">
                      <h4>Copy-Move Detection</h4>
                      <p className="tamper-score">Score: <strong>{(result.tampering?.copy_move?.score || 0).toFixed(3)}</strong></p>
                      {result.copy_move_url && (
                        <div className="heatmap">
                          <img src={`${API}${result.copy_move_url}`} alt="Copy-Move Visualization" />
                        </div>
                      )}
                    </div>

                    {/* Noise */}
                    <div className="tampering-card">
                      <h4>Noise Consistency</h4>
                      <p className="tamper-score">Score: <strong>{(result.tampering?.noise?.score || 0).toFixed(3)}</strong></p>
                      {result.tampering?.noise?.suspicious_blocks !== undefined && (
                        <p>Suspicious Blocks: {result.tampering.noise.suspicious_blocks}/{result.tampering.noise.total_blocks}</p>
                      )}
                    </div>

                    {/* Edge */}
                    <div className="tampering-card">
                      <h4>Edge Consistency</h4>
                      <p className="tamper-score">Score: <strong>{(result.tampering?.edge?.score || 0).toFixed(3)}</strong></p>
                      {result.tampering?.edge?.details && <p>{result.tampering.edge.details}</p>}
                    </div>
                  </div>

                  <div className="section-box" style={{ marginTop: '20px' }}>
                    <p><strong>Combined Tampering Score:</strong> {(result.tampering?.combined_score || result.forgery_score || 0).toFixed(4)}</p>
                  </div>
                </div>
              )}

              {/* Face Tab */}
              {activeTab === 'face' && (
                <div>
                  <h3>👤 Face Verification Results</h3>
                  {result.face?.face_detected ? (
                    <div className="face-section">
                      <div className="face-top">
                        {result.face_image_url && (
                          <div className="face-image">
                            <img src={`${API}${result.face_image_url}`} alt="Detected Face" />
                            <p>Detected Face</p>
                          </div>
                        )}
                        <div className="face-details">
                          <p>Faces Found: <strong>{result.face.num_faces}</strong></p>

                          {result.face.quality && (
                            <div className="face-quality">
                              <h4>Quality Checks</h4>
                              <p>Overall Quality: <strong>{(result.face.quality.quality_score * 100).toFixed(1)}%</strong></p>
                              {result.face.quality.checks && Object.entries(result.face.quality.checks).map(([k, v]) => (
                                <p key={k}>
                                  {v ? '✅' : '❌'} {k.replace(/_/g, ' ')}
                                </p>
                              ))}
                            </div>
                          )}

                          {result.face.tampering && (
                            <div className="face-tampering">
                              <h4>Photo Tampering Check</h4>
                              <p>Tampering Score: <strong>{(result.face.tampering.tampering_score * 100).toFixed(1)}%</strong></p>
                              {result.face.tampering.flags?.map((f, i) => (
                                <p key={i} className="flag-item warning">🚩 {f.replace(/_/g, ' ')}</p>
                              ))}
                            </div>
                          )}
                        </div>
                      </div>

                      {result.face.comparison && (
                        <div className="face-match section-box">
                          <h4>🆔 Face Match Result</h4>
                          <div className={`verdict ${result.face.comparison.match_verdict === 'Match' ? 'genuine' : 'fake'}`}>
                            {result.face.comparison.match_verdict}
                          </div>
                          <p>Match Score: <strong>{(result.face.comparison.match_score * 100).toFixed(1)}%</strong></p>
                          <p>Histogram Score: {result.face.comparison.histogram_score?.toFixed(3)}</p>
                          <p>Structural Score: {result.face.comparison.structural_score?.toFixed(3)}</p>
                        </div>
                      )}
                    </div>
                  ) : (
                    <div className="section-box">
                      <p>👤 No face detected in the uploaded document.</p>
                      <p style={{color: 'var(--text-muted)', fontSize: '14px'}}>
                        This may indicate a document without a photo, or the photo could not be located.
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}

        {/* History */}
        {history.length > 0 && (
          <div className="history-section">
            <h3>📜 Recent Scan History</h3>
            <div className="history-list">
              {history.slice(0, 10).map((item, i) => (
                <div className="history-item" key={i}>
                  <span className="history-filename">{item.filename}</span>
                  <span className={`history-verdict ${getVerdictClass(item.verdict)}`}>{item.verdict}</span>
                  <span className={`risk-level small ${getRiskClass(item.risk_level)}`}>{item.risk_level || '—'}</span>
                  <span className="history-type">{item.doc_type}</span>
                  <span className="history-time">{item.timestamp}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </>
  );
}

export default App;
